  "sodium-nitroprusside": {"formula":"NO Donor • Sodium Nitroprusside (Na2[Fe(CN)5NO])","svg":"<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 320 220' width='320' height='220'>\n  <!-- Octahedral Complex Scaffold -->\n  <circle cx='160' cy='105' r='18' fill='#ea580c' stroke='#c2410c' stroke-width='2'/>\n  <text x='160' y='110' font-size='10' font-weight='800' fill='#fff' text-anchor='middle'>Fe²⁺</text>\n  <!-- 4 Equatorial CN ligands -->\n  <line x1='160' y1='105' x2='235' y2='105' stroke='#94a3b8' stroke-width='2'/>\n  <text x='245' y='109' font-size='9' font-weight='bold' fill='#38bdf8'>CN⁻</text>\n  <line x1='160' y1='105' x2='85' y2='105' stroke='#94a3b8' stroke-width='2'/>\n  <text x='65' y='109' font-size='9' font-weight='bold' fill='#38bdf8'>CN⁻</text>\n  <line x1='160' y1='105' x2='210' y2='65' stroke='#94a3b8' stroke-width='2'/>\n  <text x='218' y='60' font-size='9' font-weight='bold' fill='#38bdf8'>CN⁻</text>\n  <line x1='160' y1='105' x2='110' y2='145' stroke='#94a3b8' stroke-width='2'/>\n  <text x='92' y='155' font-size='9' font-weight='bold' fill='#38bdf8'>CN⁻</text>\n  <!-- Axial Trans CN -->\n  <line x1='160' y1='105' x2='160' y2='165' stroke='#94a3b8' stroke-width='2'/>\n  <text x='160' y='178' font-size='9' font-weight='bold' fill='#38bdf8' text-anchor='middle'>CN⁻</text>\n  <!-- Axial Nitrosyl NO+ Ligand -->\n  <line x1='160' y1='105' x2='160' y2='45' stroke='#ef4444' stroke-width='2.5'/>\n  <circle cx='160' cy='42' r='8' fill='#ef4444'/>\n  <text x='160' y='30' font-size='9' font-weight='800' fill='#f87171' text-anchor='middle'>NO⁺ (Nitrosyl)</text>\n  <!-- Counterions -->\n  <rect x='30' y='35' width='45' height='22' rx='6' fill='#1e293b' stroke='#f59e0b' stroke-width='1.2'/>\n  <text x='52' y='50' font-size='9' font-weight='800' fill='#fcd34d' text-anchor='middle'>2 Na⁺</text>\n  <text x='160' y='205' font-size='10' font-weight='700' fill='#cbd5e1' text-anchor='middle'>Sodium Nitroprusside dihydrate</text>\n</svg>"},
